//! Bundled radar site list, generated by `hookecho-data sites` from NOAA
//! NCEI's public station list (docs/PROVENANCE.md).

use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SiteKind {
    Nexrad,
    Tdwr,
    /// Research/test WSR-88Ds (hidden unless the user opts in).
    Research,
}

#[derive(Clone, Debug)]
pub struct Site {
    pub id: String,
    pub name: String,
    /// Two-letter state/territory, empty outside the US.
    pub state: String,
    pub lat: f64,
    pub lon: f64,
    pub elevation_m: f64,
    pub kind: SiteKind,
}

const SITES_TSV: &str = include_str!("../data/sites.tsv");

/// All bundled sites, sorted by ID.
pub fn all() -> &'static [Site] {
    static SITES: OnceLock<Vec<Site>> = OnceLock::new();
    SITES.get_or_init(|| parse(SITES_TSV))
}

pub fn by_id(id: &str) -> Option<&'static Site> {
    all().iter().find(|s| s.id.eq_ignore_ascii_case(id))
}

/// Nearest site of `kind` to (lat, lon), with its distance in km.
pub fn nearest(lat: f64, lon: f64, kind: SiteKind) -> Option<(&'static Site, f64)> {
    all()
        .iter()
        .filter(|s| s.kind == kind)
        .map(|s| (s, crate::geo::range_bearing((lat, lon), (s.lat, s.lon)).0))
        .min_by(|a, b| a.1.total_cmp(&b.1))
}

/// Parses the TSV format written by hookecho-data:
/// `id  name  state  lat  lon  elevation_m  kind` (`#` lines are comments).
pub fn parse(tsv: &str) -> Vec<Site> {
    let mut v: Vec<Site> = tsv
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            if f.len() != 7 {
                return None;
            }
            Some(Site {
                id: f[0].into(),
                name: f[1].into(),
                state: f[2].into(),
                lat: f[3].parse().ok()?,
                lon: f[4].parse().ok()?,
                elevation_m: f[5].parse().ok()?,
                kind: match f[6] {
                    "TDWR" => SiteKind::Tdwr,
                    "RESEARCH" => SiteKind::Research,
                    _ => SiteKind::Nexrad,
                },
            })
        })
        .collect();
    v.sort_by(|a, b| a.id.cmp(&b.id));
    v
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_list_is_complete() {
        let s = all();
        assert!(
            s.iter().filter(|s| s.kind == SiteKind::Nexrad).count() >= 155,
            "lost NEXRAD sites"
        );
        assert_eq!(by_id("KOUN").unwrap().kind, SiteKind::Research);
        let ktlx = by_id("KTLX").unwrap();
        assert_eq!(ktlx.name, "Oklahoma City");
        assert!((ktlx.lat - 35.3334).abs() < 1e-3 && (ktlx.lon + 97.2778).abs() < 1e-3);
    }

    #[test]
    fn nearest_to_norman_is_ktlx() {
        let (s, d) = nearest(35.22, -97.44, SiteKind::Nexrad).unwrap();
        assert_eq!(s.id, "KTLX");
        assert!(d < 25.0);
    }
}
